import React, { useState } from 'react';
import { Home, Bell, MessageCircle, Heart, Search, MoreHorizontal, Send, MessageSquare, Image, Video } from 'lucide-react';

export default function AlohaDashboard() {
  const [activeTab, setActiveTab] = useState('home');

  const stories = [
    { name: 'Kevin', avatar: '🧑', active: true },
    { name: 'Alice', avatar: '👩', active: false },
    { name: 'Zayn', avatar: '🧔', active: false },
    { name: 'Miya', avatar: '👩‍🦰', active: true },
    { name: 'Steven', avatar: '👨', active: false },
    { name: 'Udina', avatar: '👨‍💼', active: false },
  ];

  const suggestions = [
    { name: 'Royan', location: 'Bandung, Indonesia', followed: false },
    { name: 'Wati', location: 'Bekasi, Indonesia', followed: true },
    { name: 'Jacks', location: 'Banten, Tangiers', followed: true },
    { name: 'Jason', location: 'Rache, Singapore', followed: false },
  ];

  const activities = [
    { user: 'Tiara.sehent', action: 'and 16 others start following you', time: '5 Min', avatar: '👩' },
    { user: 'Ui_Manola', action: 'Commented on your post : Amazing', time: '8 Min', avatar: '👨' },
    { user: 'Mayz', action: 'Start following you', time: '2 Min', avatar: '👤' },
  ];

  const yesterdayActivities = [
    { user: 'Hanna.ui', action: 'and 402 others liked your posts', time: '1 Day', avatar: '👩' },
    { user: 'Mawang21', action: 'Commented on your post : Very Useful!!', time: '1 Day', avatar: '👨' },
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center space-x-8">
            <h1 className="text-2xl font-bold">⚡ ALOHA</h1>
            <nav className="hidden md:flex items-center space-x-6">
              <button className={`p-2 rounded-lg ${activeTab === 'home' ? 'bg-gray-900 text-white' : 'text-gray-600'}`}>
                <Home size={20} />
              </button>
              <button className="p-2 text-gray-600 hover:text-gray-900">
                <MessageCircle size={20} />
              </button>
              <button className="p-2 text-gray-600 hover:text-gray-900">
                <MessageSquare size={20} />
              </button>
              <button className="p-2 text-gray-600 hover:text-gray-900">
                <Heart size={20} />
              </button>
              <button className="p-2 text-gray-600 hover:text-gray-900">
                <Bell size={20} />
              </button>
            </nav>
          </div>
          <div className="flex items-center space-x-4">
            <div className="relative">
              <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
              <input
