                placeholder="Search"
                className="pl-10 pr-4 py-2 bg-gray-100 rounded-lg w-64 focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-8 h-8 bg-pink-500 rounded-full flex items-center justify-center text-white font-bold">
                A
              </div>
              <span className="font-medium">Aldsay</span>
            </div>
          </div>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 py-6 grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Sidebar */}
        <div className="lg:col-span-1 space-y-4">
          {/* Profile Card */}
          <div className="bg-gradient-to-br from-blue-400 via-yellow-300 to-pink-400 rounded-2xl p-6 text-white relative overflow-hidden">
            <button className="absolute top-4 right-4 p-1 bg-white/20 rounded-full">
              <MoreHorizontal size={18} />
            </button>
            <div className="relative">
              <div className="w-20 h-20 bg-pink-500 rounded-full mx-auto mb-4 flex items-center justify-center text-3xl">
                👩
              </div>
              <div className="absolute bottom-0 right-1/3 bg-blue-600 rounded-full p-1">
                <span className="text-xs">+</span>
              </div>
            </div>
            <div className="flex justify-between text-center mb-4">
              <div>
                <div className="font-bold text-lg">2002</div>
                <div className="text-xs opacity-90">Followers</div>
              </div>
              <div>
                <div className="font-bold text-lg">2022</div>
                <div className="text-xs opacity-90">Following</div>
              </div>
            </div>
            <div className="space-y-1">
              <div className="font-bold">Aldsay Pro</div>
              <div className="text-sm font-medium">Entrepreneur</div>
              <p className="text-xs opacity-90 mt-2">
                Aku suka bermain bola dan mulai menjelajahi hobbi hingga sukses!
              </p>
            </div>
          </div>

          {/* Post Box */}
          <div className="bg-white rounded-2xl p-4 shadow-sm">
            <input
              type="text"
              placeholder="Share your thoughts..."
              className="w-full p-3 bg-gray-50 rounded-lg mb-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <div className="flex items-center justify-between">
              <div className="flex space-x-4">
                <button className="flex items-center space-x-2 text-gray-600 hover:text-gray-900">
                  <Image size={20} />
                  <span className="text-sm">Image</span>
                </button>
                <button className="flex items-center space-x-2 text-gray-600 hover:text-gray-900">
                  <Video size={20} />
                  <span className="text-sm">Video</span>
                </button>
              </div>
              <button className="bg-blue-500 text-white px-6 py-2 rounded-lg hover:bg-blue-600 flex items-center space-x-2">
                <Send size={16} />
                <span>Post</span>
              </button>
            </div>
          </div>

          {/* Last Viewed */}
          <div className="bg-white rounded-2xl p-4 shadow-sm">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold">Last viewed</h3>
              <button className="text-blue-500 text-sm">See all</button>
            </div>
            <div className="space-y-3">
              {['MaJid.official', 'Tulusui', 'Bonano3'].map((name, i) => (
                <div key={i} className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-pink-400 to-orange-400 rounded-full"></div>
                    <div>
                      <div className="font-medium text-sm">{name}</div>
                      <div className="text-xs text-gray-500">MPL Indonesia</div>
                    </div>
                  </div>
                  <button className="text-gray-400 hover:text-gray-600">×</button>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Main Feed */}
        <div className="lg:col-span-1 space-y-4">
          {/* Stories */}
          <div className="bg-white rounded-2xl p-4 shadow-sm">
