                    story.active ? 'bg-gradient-to-br from-purple-500 to-pink-500 p-0.5' : 'bg-gray-200'
                  }`}>
                    <div className="w-full h-full bg-white rounded-full flex items-center justify-center">
                      {story.avatar}
                    </div>
                  </div>
                  <span className="text-xs">{story.name}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Post 1 */}
          <div className="bg-white rounded-2xl shadow-sm overflow-hidden">
            <div className="p-4 flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-pink-400 rounded-full flex items-center justify-center text-xl">👨</div>
                <div>
                  <div className="font-bold">Hanabi</div>
                  <div className="text-xs text-gray-500">Jayapura, Indonesia</div>
                </div>
              </div>
              <button><MoreHorizontal size={20} className="text-gray-400" /></button>
            </div>
            <div className="px-4 pb-3">
              <p className="text-sm text-gray-700">
                Telepon adalah perawat dengan listat dan kawat, untuk bercekalap-cekalap antara dua orang yang berjalan tempatnya. <span className="text-blue-500 cursor-pointer">Read More</span>
              </p>
            </div>
