              <img src="data:image/svg+xml,%3Csvg width='400' height='250' xmlns='http://www.w3.org/2000/svg'%3E%3Crect width='400' height='250' fill='%23fbbf24'/%3E%3Ctext x='50%25' y='50%25' font-size='60' text-anchor='middle' dy='.3em'%3E📞%3C/text%3E%3C/svg%3E" alt="Phone" className="w-full" />
            </div>
            <div className="p-4 flex items-center justify-between border-t">
              <div className="flex items-center space-x-1">
                <div className="w-6 h-6 bg-pink-400 rounded-full"></div>
                <span className="text-sm ml-1">Add Commentor</span>
              </div>
              <div className="flex items-center space-x-4 text-gray-600">
                <div className="flex items-center space-x-1">
                  <Heart size={18} />
                  <span className="text-sm">2.1K</span>
                </div>
                <div className="flex items-center space-x-1">
                  <MessageCircle size={18} />
                  <span className="text-sm">102</span>
