                <div className="flex items-center space-x-1">
                  <Send size={18} />
                  <span className="text-sm">42</span>
                </div>
              </div>
            </div>
          </div>

          {/* Post 2 */}
          <div className="bg-white rounded-2xl shadow-sm">
            <div className="p-4 flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-orange-400 rounded-full flex items-center justify-center text-xl">👨</div>
                <div>
                  <div className="font-bold">Ean Yeager</div>
                  <div className="text-xs text-gray-500">Higashikata, Japan</div>
                </div>
              </div>
              <button><MoreHorizontal size={20} className="text-gray-400" /></button>
            </div>
            <div className="px-4 pb-4">
              <p className="text-sm text-gray-700">
                To all the subjects of Ymir, my name is Ean Yeager, My objective is to protect the people of Paradis, the wall titans s...<span className="text-blue-500 cursor-pointer">Read More</span>
              </p>
            </div>
          </div>
        </div>

        {/* Right Sidebar */}
        <div className="lg:col-span-1 space-y-4">
          {/* Suggestions */}
          <div className="bg-white rounded-2xl p-4 shadow-sm">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold">Suggested for you</h3>
              <button className="text-blue-500 text-sm">See all</button>
            </div>
            <div className="space-y-3">
              {suggestions.map((user, i) => (
                <div key={i} className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 bg-gradient-to-br from-blue-400 to-purple-400 rounded-full"></div>
                    <div>
                      <div className="font-medium text-sm">{user.name}</div>
                      <div className="text-xs text-gray-500">{user.location}</div>
                    </div>
                  </div>
                  {user.followed ? (
                    <button className="text-sm text-gray-600 px-3 py-1 border border-gray-300 rounded-lg">
                      Followed
                    </button>
                  ) : (
                    <button className="text-sm text-white bg-blue-500 px-4 py-1 rounded-lg hover:bg-blue-600">
                      Follow
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Latest Activity */}
          <div className="bg-white rounded-2xl p-4 shadow-sm">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold">Latest activity</h3>
              <button><MoreHorizontal size={20} className="text-gray-400" /></button>
            </div>

            <div className="mb-4">
              <div className="text-sm font-semibold mb-3">Today</div>
              <div className="space-y-3">
                {activities.map((activity, i) => (
                  <div key={i} className="flex items-start space-x-3">
                    <div className="w-8 h-8 bg-gradient-to-br from-yellow-400 to-orange-400 rounded-full flex items-center justify-center text-sm flex-shrink-0">
                      {activity.avatar}
